INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (93773,0,0,'Ah, I\'ll wager Eitrigg sent you. His concern is noble, but unnecessary.',12,0,100.0,0,0,0,114651,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (93773,1,0,'Death is our likely end on those shores. You know this, yet I can see the determination in your eyes. Perhaps you have honor to regain there as well.',12,0,100.0,0,0,0,114668,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (93775,0,0,'My thanks, champion. I will seek out Thrall and see if he can help.',12,0,100.0,0,0,0,114649,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (93823,0,0,'',12,0,100.0,0,0,0,0,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (93823,1,0,'',12,0,100.0,0,0,0,0,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (93823,2,0,'Across the way lies the Arena of Glory, where warriors vie for supremacy in epic combat. Before us lies the Great Mead Hall where drink and stories flow freely!',12,0,100.0,0,0,0,105450,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (93823,3,0,'',12,0,100.0,0,0,0,0,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (96183,3,0,'Look there, upon that terrible sight. How many disasters must we face before we can at last find peace?',12,0,100.0,0,0,63543,114697,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (96469,0,0,'Go now. Hruthnir waits at the Sky Launch to aid you.',12,0,100.0,0,0,0,106221,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (96469,1,0,'Thorim... son! Hold them off! I shall send my champions to your aid.',14,0,100.0,1,0,68400,119684,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (96469,2,0,'Let it be known! Today, thanks to the new Battlelord of the Valarjar we have won our first decisive victory against the Legion in one of their own worlds.',14,0,100.0,1,0,69283,119685,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (96469,3,0,'Victory to the Valarjar! Victory to the Battlelord!',14,0,100.0,25,0,69284,119687,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (96488,3,0,'A raven flies up and hovers expectantly. It has a message!',41,0,100.0,0,0,0,97467,0,'LegionCore');
